// 日報（画像）を取り出し、まだ通知していないものだけを返す。
// 通知済みリストはワークフローの静的データに保存されるため、
// n8nを再起動しても重複通知しません。
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const seen = new Set(store.seen);

const records = $json.records || [];
const pairKey = (code) => { const m = code.match(/_(\d+)$/); return m ? m[1] : ''; };
const isSub = (f) => f && Array.isArray(f.value) && f.value[0] && f.value[0].value && typeof f.value[0].value === 'object';

const items = [];
for (const rec of records) {
  let team = null;
  for (const [, f] of Object.entries(rec)) if (f && f.type === 'DROP_DOWN' && f.value) { team = f.value; break; }
  for (const [, f] of Object.entries(rec)) {
    if (!isSub(f)) continue;
    for (const row of f.value) {
      let date = null; const names = {}, files = {};
      for (const [code, cell] of Object.entries(row.value)) {
        if (!cell) continue;
        if (cell.type === 'DATETIME' && cell.value) date = String(cell.value).slice(0, 10);
        else if (cell.type === 'SINGLE_LINE_TEXT') names[pairKey(code)] = cell.value || null;
        else if (cell.type === 'FILE') files[pairKey(code)] = Array.isArray(cell.value) ? cell.value : [];
      }
      for (const k of Object.keys(files)) for (const file of (files[k] || [])) {
        items.push({ id: file.fileKey, date, reporter: names[k] || null, team,
                     fileName: file.name, contentType: file.contentType });
      }
    }
  }
}

// 初回実行時は既存分を通知しない（LINEが埋まるのを防ぐ）
if (!store.initialized) {
  store.initialized = true;
  store.seen = items.map(x => x.id);
  return [{ json: { firstRun: true, count: items.length, fresh: [] } }];
}

const fresh = items.filter(x => !seen.has(x.id)).slice(0, 5); // 1回5件まで
return fresh.length ? fresh.map(x => ({ json: x })) : [{ json: { none: true } }];

// Claudeの応答を整形してLINEメッセージを作る。失敗しても通知はする。
const info = $('新規提出を検出').item.json;
let a = null;
try {
  const t = ($json.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  let s = t.trim();
  const f = s.match(/```(?:json)?\s*([\s\S]*?)```/i); if (f) s = f[1].trim();
  const i = s.indexOf('{'), j = s.lastIndexOf('}'); if (i > -1 && j > -1) s = s.slice(i, j + 1);
  a = JSON.parse(s);
} catch (e) { a = null; }

const who = info.reporter || '（氏名不明）';
const team = info.team ? `（${info.team}）` : '';
const head = a && a.urgent ? '🚨 要対応の日報が届きました' : '📝 日報が届きました';
const L = [`${head}（${info.date}）`, '', `${who}さん${team}`, ''];
if (a) {
  L.push(`【要点】${a.summary || '情報不足'}`);
  if (Array.isArray(a.done) && a.done.length) L.push('', '【完了】', ...a.done.map(x => '・' + x));
  if (Array.isArray(a.tomorrow) && a.tomorrow.length) L.push('', '【明日】', ...a.tomorrow.map(x => '・' + x));
  if (a.urgent && a.urgent_reason) L.push('', '⚠️ ' + a.urgent_reason);
  if (a.comment && a.comment !== '特記事項なし') L.push('', '🤖 AIコメント', a.comment);
} else {
  L.push('（内容の自動要約に失敗しました）');
}
L.push('', '↑ 日報の原本を添付しています。');
const text = L.join('\n').slice(0, 4800);
// LINE用(messages) と Chatwork用(title/body) の両方を返す
const title = L[0];
const body = L.slice(1).join('\n').trim().slice(0, 3800);
// 画像(バイナリ)を引き継いで、次のChatworkノードで添付できるようにする
const bin = $('日報画像を取得').first().binary;
return [{ json: { id: info.id, urgent: !!(a && a.urgent), title, body, text, messages: [{ type: 'text', text }] }, binary: bin }];

// 送信できたものだけを通知済みに記録する（失敗分は次回再送される）
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const id = $('通知文を作成').item.json.id;
if (id && !store.seen.includes(id)) store.seen.push(id);
// 記録が増えすぎないよう直近1000件に保つ
if (store.seen.length > 1000) store.seen = store.seen.slice(-1000);
return [{ json: { recorded: id, total: store.seen.length } }];
